import rawPosts from './posts.json';

// posts.json is generated by scripts/blog/sync.mjs (run daily by .github/workflows/sync-blog.yml).
// Don't edit it by hand except to remove a post; see scripts/blog/post.mjs for the Post shape.

const byNewest = (a, b) => Date.parse(b.publishedAt) - Date.parse(a.publishedAt);

export const posts = [...rawPosts].sort(byNewest);

export const latestPosts = (n, list = posts) => list.slice(0, n);

// Dates are stored in UTC; format in UTC too so the day doesn't shift across time zones.
const dateFormat = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
export const formatDate = (iso) => dateFormat.format(new Date(iso));

// Display info per Post.source. Adding a source only needs an entry here.
export const sourceMeta = {
  medium: { label: 'Medium' },
  linkedin: { label: 'LinkedIn' },
};
